 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    comp = [[-1] * w for _ in range(h)]
    marked = {}
    cid = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or comp[r][c] != -1:
                continue
            q = deque([(r, c)])
            comp[r][c] = cid
            colors = set()
            while q:
                y, x = q.popleft()
                if grid[y][x] > 1:
                    colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and comp[yy][xx] == -1:
                        comp[yy][xx] = cid
                        q.append((yy, xx))
            if colors:
                marked[cid] = min(colors)
            cid += 1

    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            k = comp[r][c]
            if k < 0 or k not in marked:
                continue
            if all(comp[y][x] == k for y in range(r - 1, r + 2) for x in range(c - 1, c + 2)):
                out[r][c] = marked[k]
    return out
